                    { title: 'SLA Near Breach', val: `${nearBreachCount} At Risk`, color: '#f59e0b' },
                    { title: 'Avg Supervisor Response', val: '1m 48s', color: '#0284c7' },
                    { title: 'Override Success Rate', val: '98.4%', color: '#10b981' }
