                                    color: '#ffffff',
                                    fontSize: '0.74rem',
                                    fontWeight: 600,
                                    padding: '0.32rem 0.65rem',
                                    borderRadius: '6px',
                                    cursor: 'pointer',
                                    boxShadow: '0 2px 6px rgba(2, 132, 199, 0.25)',
